1	import { test, describe } from 'node:test';
2	import assert from 'node:assert/strict';
3	
4	import { buildInvoice, totalRevenueForMonth } from '../src/projections/billing.ts';
5	import { billableMinutes, rawMinutesBetween } from '../src/lib/duration.ts';
6	import type { DomainEvent } from '../src/domain/events.ts';
7	
8	function completedBooking(opts: {
9	  id: string; user?: string; resourceId?: string;
10	  startAt: string; endAt: string; actualStartAt: string; actualEndAt: string;
11	}): DomainEvent[] {
12	  const user = opts.user ?? 'u-pat';
13	  return [
14	    {
15	      type: 'BookingRequested', bookingId: opts.id, occurredAt: opts.startAt, actorId: user,
16	      userId: user, userRole: 'STUDENT', resourceId: opts.resourceId ?? 'gpu-a100-01',
17	      startAt: opts.startAt, endAt: opts.endAt, requiresApproval: false,
18	    },
19	    { type: 'BookingStarted', bookingId: opts.id, occurredAt: opts.actualStartAt, actorId: user, actualStartAt: opts.actualStartAt },
20	    { type: 'BookingCompleted', bookingId: opts.id, occurredAt: opts.actualEndAt, actorId: user, actualEndAt: opts.actualEndAt },
21	  ] as DomainEvent[];
22	}
23	
24	describe('การปัดเวลาเพื่อคิดค่าบริการ', () => {
25	  test('REQ-35 ปัดขึ้นเป็นจำนวนเท่าของ 15 นาที', () => {
26	    // ใช้จริง 2 ชม. 3 นาที -> 2 ชม. 15 นาที
27	    assert.equal(billableMinutes('2026-05-01T09:00:00.000Z', '2026-05-01T11:03:00.000Z'), 135);
28	  });
29	
30	  test('REQ-35 ลงตัวพอดีแล้วไม่ปัดเพิ่ม', () => {
31	    assert.equal(billableMinutes('2026-05-01T09:00:00.000Z', '2026-05-01T11:00:00.000Z'), 120);
32	  });
33	
34	  test('ใช้จริง 1 นาที ยังคิดขั้นต่ำ 15 นาที', () => {
35	    assert.equal(billableMinutes('2026-05-01T09:00:00.000Z', '2026-05-01T09:01:00.000Z'), 15);
36	  });
37	
38	  test('ช่วงเวลาติดลบหรือเป็นศูนย์ คิดเป็น 0', () => {
39	    assert.equal(billableMinutes('2026-05-01T09:00:00.000Z', '2026-05-01T09:00:00.000Z'), 0);
40	  });
41	
42	  test('นาทีดิบไม่ถูกปัด', () => {
43	    assert.equal(rawMinutesBetween('2026-05-01T09:00:00.000Z', '2026-05-01T11:03:00.000Z'), 123);
44	  });
45	});
46	
47	describe('ใบแจ้งหนี้', () => {
48	  test('REQ-34 A100 คิด 40 บาทต่อชั่วโมง', () => {
49	    const events = completedBooking({
50	      id: 'b1', startAt: '2026-05-10T09:00:00.000Z', endAt: '2026-05-10T12:00:00.000Z',
51	      actualStartAt: '2026-05-10T09:00:00.000Z', actualEndAt: '2026-05-10T12:00:00.000Z',
52	    });
53	    assert.equal(buildInvoice(events, 'u-pat', '2026-05').totalBaht, 120);
54	  });
55	
56	  test('REQ-34 V100 คิด 20 บาทต่อชั่วโมง', () => {
57	    const events = completedBooking({
58	      id: 'b2', resourceId: 'gpu-v100-01',
59	      startAt: '2026-05-10T09:00:00.000Z', endAt: '2026-05-10T12:00:00.000Z',
60	      actualStartAt: '2026-05-10T09:00:00.000Z', actualEndAt: '2026-05-10T12:00:00.000Z',
61	    });
62	    assert.equal(buildInvoice(events, 'u-pat', '2026-05').totalBaht, 60);
63	  });
64	
65	  test('REQ-33 คิดตามเวลาที่ใช้จริง ไม่ใช่เวลาที่จอง', () => {
66	    const events = completedBooking({
67	      id: 'b3', startAt: '2026-05-10T09:00:00.000Z', endAt: '2026-05-10T17:00:00.000Z',
68	      actualStartAt: '2026-05-10T09:00:00.000Z', actualEndAt: '2026-05-10T11:00:00.000Z',
69	    });
70	    assert.equal(buildInvoice(events, 'u-pat', '2026-05').totalBaht, 80);   // 2 ชม. ไม่ใช่ 8
71	  });
72	
73	  test('REQ-35 เศษนาทีถูกปัดขึ้นก่อนคิดเงิน', () => {
74	    const events = completedBooking({
75	      id: 'b4', startAt: '2026-05-10T09:00:00.000Z', endAt: '2026-05-10T12:00:00.000Z',
76	      actualStartAt: '2026-05-10T09:00:00.000Z', actualEndAt: '2026-05-10T11:03:00.000Z',
77	    });
78	    const inv = buildInvoice(events, 'u-pat', '2026-05');
79	    assert.equal(inv.lines[0].billableMinutes, 135);
80	    assert.equal(inv.totalBaht, 90);   // 135/60 * 40
81	  });
82	
83	  test('REQ-38 นับเฉพาะเดือนที่ระบุ', () => {
84	    const events = [
85	      ...completedBooking({ id: 'b5', startAt: '2026-05-10T09:00:00.000Z', endAt: '2026-05-10T10:00:00.000Z', actualStartAt: '2026-05-10T09:00:00.000Z', actualEndAt: '2026-05-10T10:00:00.000Z' }),
86	      ...completedBooking({ id: 'b6', startAt: '2026-06-10T09:00:00.000Z', endAt: '2026-06-10T10:00:00.000Z', actualStartAt: '2026-06-10T09:00:00.000Z', actualEndAt: '2026-06-10T10:00:00.000Z' }),
87	    ];
88	    assert.equal(buildInvoice(events, 'u-pat', '2026-05').lines.length, 1);
89	    assert.equal(buildInvoice(events, 'u-pat', '2026-06').lines.length, 1);
90	  });
91	
92	  test('การจองของผู้ใช้อื่นไม่ปรากฏในใบแจ้งหนี้', () => {
93	    const events = completedBooking({
94	      id: 'b7', user: 'u-ming',
95	      startAt: '2026-05-10T09:00:00.000Z', endAt: '2026-05-10T10:00:00.000Z',
